import 'package:flutter/material.dart';import 'package:flutter_bloc/flutter_bloc.dart';import '../../../../../../Core/Utils/Widget/TextField/build_text_field.dart';import '../../../../../../Core/Utils/Widget/custom_massage.dart';import '../../../../../../Core/Utils/Widget/default_app_bar.dart';import '../../../../../../Core/Utils/Widget/loading_animation.dart';import '../../domain/repositories/cart_repo_impl.dart';import '../../domain/useCases/cart_use_case.dart';import '../Cubit/Cart/cart_state.dart';import '../../../../../../Core/Utils/Extensions/localizations_extension.dart';import '../../../ProductsDetails/presentation/components/build_button_add_cart.dart';import '../Cubit/Cart/cart_cubit.dart';import '../widgets/body_page_cart_items.dart';import '../widgets/no_item.dart';final TextEditingController textCoupon = TextEditingController();class CartScreen extends StatelessWidget {  const CartScreen({super.key});  @override  Widget build(BuildContext context) {    final local = context.local;    return BlocProvider(      create: (context) => CartCubit(        GetCartUseCase(          CartRepoImpl(),        ),        UpdateCartUseCase(          CartRepoImpl(),        ),        RemoveItemUseCase(          CartRepoImpl(),        ),      )..initItems(),      child: BlocBuilder<CartCubit, CartStates>(        builder: (context, state) {          return Scaffold(            appBar: DefaultAppBar(local: local),            body: state.loading == true                ? CustomLoadingAnimation()                : state.loading == null                    ? NoItemsCart(local: local)                    : state.success == false                        ? CustomMassage(massage: state.error.toString())                        : BodyPageCartItems(                            cartItems: state.cartItems?.cartItems ?? [],                            local: local,                          ),            persistentFooterButtons: [              BuildButtonBottomScreen(                nameButtonBuy: context.local.BuyNow,                onPressed: () {},                price: state.cartItems?.summary?.grandTotal.toString() ?? "0",                            ),              Align(                  child: DefaultTextFormField(                isText: false,                text: local.CouponCode,                type: TextInputType.none,                controller: textCoupon,              )),            ],          );        },      ),    );  }}